cd /c/Dot; for f in test/server.test.js test/agents.test.js test/context.test.js; do node -e "
const fs=require('fs');const p='$f';let s=fs.readFileSync(p,'utf8');
const a='const freshPort = () => { let port; do port = 5190 + Math.floor(Math.random() * 2000); while (usedPorts.has(port)); usedPorts.add(port); return port; };';
if(!s.includes(a)) throw new Error(p+' missing');
s=s.replace(a,'// fetch refuses some ports outright (\"bad port\": 6000 X11, 6566, 6665-6669 IRC, 6697), like browsers do.\nconst BLOCKED = new Set([6000, 6566, 6665, 6666, 6667, 6668, 6669, 6697]);\nconst freshPort = () => { let port; do port = 5190 + Math.floor(Math.random() * 2000); while (usedPorts.has(port) || BLOCKED.has(port)); usedPorts.add(port); return port; };');
fs.writeFileSync(p,s);console.log('ok',p)"; done; grep -rn "5190 + Math.floor" test/*.js | grep -v freshPort | head

cd /c/Dot; node --input-type=module -e "
const bad = [];
await Promise.all(Array.from({ length: 2001 }, (_, i) => 5190 + i).map(async (port) => {
  try { await fetch('http://[REDACTED:ip]:' + port + '/', { signal: AbortSignal.timeout(3000) }); } catch (e) { if (/bad port/i.test(String(e.cause?.message ?? e.message))) bad.push(port); }
}));
console.log('blocked by fetch in 5190-7190:', bad.sort((a, b) => a - b).join(', '));"
